import {englishQuestions,calculateEnglish} from './english-model.mjs';
import {englishTypes} from './english-types.mjs';
import {homeAssets} from './home-assets.mjs';
import {typeImages} from './type-images.mjs';
const root=document.querySelector('#app'),key='persona-spectrum-english-60-v1';
let answers={},page=0;
try{const saved=JSON.parse(localStorage.getItem(key));if(saved){answers=Object.fromEntries(englishQuestions.filter(q=>Number.isInteger(saved.answers?.[q.id])&&Math.abs(saved.answers[q.id])<=3).map(q=>[q.id,saved.answers[q.id]]));page=Math.min(9,Math.max(0,Number.isInteger(saved.page)?saved.page:0));}}catch{}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{try{localStorage.setItem(key,JSON.stringify({answers,page}));}catch{}};
function home(){root.innerHTML=`<section class="landing"><p class="eyebrow">PERSONA SPECTRUM</p><h1>It’s so incredible to finally be understood.</h1><p>Discover your personality, explore your strengths,<br>and understand what makes you, you.</p><a class="primary" href="#test">Take the personality test <span>→</span></a><small>60 questions · About 10 minutes · Free English report</small><picture><source media="(min-width:768px)" srcset="${homeAssets['hero-desktop']}"><img src="${homeAssets['hero-mobile']}" alt="Friends with different personalities gather around a campfire"></picture></section><section class="types"><h2>Explore the 16 personality types</h2><p>Preview the imported reports, including their original English chapters and illustrations.</p><div class="type-grid">${Object.entries(englishTypes).map(([code,t])=>`<article class="type-card"><a href="./reports/${code}-A.html"><img src="${typeImages[code].avatar.src}" alt="${escape(t.name)}"><strong>${escape(t.name)}</strong><span>${code}</span></a><div class="variant-links"><a href="./reports/${code}-A.html">Assertive · A</a><a href="./reports/${code}-T.html">Turbulent · T</a></div></article>`).join('')}</div></section>`;}
function quiz(){
 const count=Object.keys(answers).length;
 root.innerHTML=`<section class="quiz"><p class="eyebrow">FREE PERSONALITY TEST</p><h1>Be yourself. Answer honestly.</h1><p>Choose what usually describes you, rather than who you would like to be.</p><div class="progress-label"><strong>Step ${page+1} of 10</strong><span>${count} / 60 answered</span></div><progress max="60" value="${count}" aria-label="Questions answered"></progress><form><div id="error" role="alert"></div>${englishQuestions.slice(page*6,page*6+6).map((q,i)=>`<fieldset id="${q.id}"><legend><small>${page*6+i+1} / 60</small>${escape(q.text)}</legend><div class="choices"><span>Agree</span>${[3,2,1,0,-1,-2,-3].map((v,n)=>`<label style="--size:${[48,40,32,24,32,40,48][n]}px;--tone:${n<3?'#539c85':n>3?'#9274a4':'#aaa7ae'}"><input type="radio" name="${q.id}" value="${v}" aria-label="${['Strongly agree','Moderately agree','Slightly agree','Neither agree nor disagree','Slightly disagree','Moderately disagree','Strongly disagree'][n]}" ${answers[q.id]===v?'checked':''}><span></span></label>`).join('')}<span>Disagree</span></div></fieldset>`).join('')}<div class="actions">${page?'<button type="button" class="secondary" id="previous">← Previous</button>':'<a href="#" class="secondary">Home</a>'}<button class="primary">${page===9?'See my results':'Next'} →</button></div></form><p class="method">Approximate scoring: each answer contributes equally to its assigned dimension. This is not the original proprietary scoring algorithm. Results describe preferences, not ability or a diagnosis. Progress stays in this browser.</p></section>`;
 root.querySelector('form').onchange=e=>{if(e.target.type==='radio'){answers[e.target.name]=Number(e.target.value);save();root.querySelector('progress').value=Object.keys(answers).length;root.querySelector('.progress-label span').textContent=`${Object.keys(answers).length} / 60 answered`;}};
 root.querySelector('#previous')?.addEventListener('click',()=>{page--;save();quiz();scrollTo(0,0);});
 root.querySelector('form').onsubmit=e=>{e.preventDefault();const missing=englishQuestions.slice(page*6,page*6+6).filter(q=>!Number.isInteger(answers[q.id]));if(missing.length){root.querySelector('#error').textContent=`Please answer the remaining ${missing.length} question${missing.length===1?'':'s'}.`;root.querySelector(`#${missing[0].id} input`).focus();return;}if(page<9){page++;save();quiz();scrollTo(0,0);}else{const result=calculateEnglish(answers);if(result.code.includes('X')||result.variant==='X'){root.innerHTML=`<section class="quiz"><h1>Your preferences are close to the middle.</h1><p>One or more dimensions are tied. A single personality type would overstate this result.</p>${result.dimensions.map(d=>`<p><strong>${d.label}</strong>: ${d.leftPct}% ${d.left} / ${100-d.leftPct}% ${d.right}</p>`).join('')}<p class="method">Approximate scoring. These values describe this set of answers, not population percentiles.</p><a class="primary" href="./index.html#test">Review my answers</a></section>`;scrollTo(0,0);return;}sessionStorage.setItem('persona-english-result',JSON.stringify(result));location.href=`./reports/${result.code}-${result.variant}.html#result=${encodeURIComponent(JSON.stringify(result))}`;}};
}
function render(){location.hash==='#test'?quiz():home();}addEventListener('hashchange',()=>{render();scrollTo(0,0);});render();
